// Synthetic searchable characteristics belong only to explicitly labelled demo assets.
function enrichDemoSearch(c){if(!c.demo||c.demoEdited||c.demoCatalogVersion>=3)return;const k=c.id%20,cat=c.category||'cars';c.condition=c.condition||(k%9===0?'repair':'used');c.sellerType=c.sellerType||(k%2?'leasing':'bank');if(!c.model)c.model=c.name.split(' · ')[0];if(['cars','trucks','machinery','vessels'].includes(cat)&&c.assetKind!=='trailer'){c.mileage=c.mileage??Number(String(c.km).replace(/[^0-9]/g,''));c.fuel=c.fuel||(cat==='trucks'||cat==='machinery'?'diesel':'petrol');c.transmission=c.transmission||(cat==='cars'?'auto':k%2?'manual':'auto');c.drive=c.drive||(cat==='cars'?k%3===0?'awd':'front':'rear');c.powerHp=c.powerHp??(cat==='trucks'?280+k*10:90+k*12)}if(['property','commercial'].includes(cat)&&c.assetKind!=='house'){c.area=c.area??(Number.parseFloat(c.engine)||35+k*7);c.rooms=c.rooms??(/Студия/i.test(c.name)?0:/Однокомнат/i.test(c.name)?1:/Двухкомнат/i.test(c.name)?2:/Трёхкомнат/i.test(c.name)?3:1+k%5);c.floor=c.floor??(1+k%9);c.totalFloors=c.totalFloors??12}if(['equipment','other'].includes(cat)){if(!c.photoExample)c.manufacturer=c.manufacturer||'Производитель '+(k%4+1)+' (демо)';c.powerKw=c.powerKw??(5+k*5)}}
